payload.message:
This UI is in a good spot for beta. The next step is to wire `Start Recording`, `Stop Recording`, and `Submit Argument` to `webkitSpeechRecognition`.

Use this state model in your React component:

```jsx
const [recordingStatus, setRecordingStatus] = useState("Idle");
const [isListening, setIsListening] = useState(false);
const [finalTranscript, setFinalTranscript] = useState("");
const [interimTranscript, setInterimTranscript] = useState("");
const recognitionRef = useRef(null);
```

Then initialize browser speech recognition:

```jsx
function getSpeechRecognition() {
  return window.SpeechRecognition || window.webkitSpeechRecognition;
}
```

Your `Start Recording` handler should:
- check browser support
- create a recognition instance
- set `continuous = true`
- set `interimResults = true`
- update `finalTranscript` and `interimTranscript` inside `onresult`

Example:

```jsx
function handleStartRecording() {
  const SpeechRecognition = getSpeechRecognition();

  if (!SpeechRecognition) {
    setRecordingStatus("Speech recognition not supported in this browser.");
    return;
  }

  const recognition = new SpeechRecognition();
  recognitionRef.current = recognition;

  recognition.continuous = true;
  recognition.interimResults = true;
  recognition.lang = "en-US";

  recognition.onstart = function () {
    setIsListening(true);
    setRecordingStatus("Listening...");
  };

  recognition.onresult = function (event) {
    let newFinal = "";
    let newInterim = "";

    for (let i = event.resultIndex; i < event.results.length; i += 1) {
      const text = event.results[i][0].transcript;

      if (event.results[i].isFinal) {
        newFinal += text + " ";
      } else {
        newInterim += text;
      }
    }

    if (newFinal) {
      setFinalTranscript((prev) => prev + newFinal);
    }

    setInterimTranscript(newInterim);
  };

  recognition.onerror = function (event) {
    setRecordingStatus(`Error: ${event.error}`);
    setIsListening(false);
  };

  recognition.onend = function () {
    setIsListening(false);
    setRecordingStatus("Idle");
  };

  recognition.start();
}
```

Your `Stop Recording` handler should be:

```jsx
function handleStopRecording() {
  if (recognitionRef.current) {
    recognitionRef.current.stop();
  }
}
```

Render the preview textarea using both transcript parts:

```jsx
value={`${finalTranscript}${interimTranscript}`}
```

Then `Submit Argument` should:
- take `finalTranscript.trim()`
- save it into your `submittedArguments`
- switch speaker
- increment turn count
- clear transcript state

Example:

```jsx
function handleSubmitArgument() {
  const cleaned = finalTranscript.trim();

  if (!cleaned) {
    return;
  }

  const nextTurn = submittedArguments.length + 1;

  setSubmittedArguments((prev) => [
    ...prev,
    {
      turn: nextTurn,
