const { DataTypes } = require("sequelize");
const { sequelize } = require("../datasource");

const DebateAnalysis = sequelize.define("DebateAnalysis", {
  caseId: {
    type: DataTypes.INTEGER,
    allowNull: false,
    unique: true,
  },
  analysis: {
    type: DataTypes.JSON,
    allowNull: false,
    defaultValue: {
      version: 1,
      lastProcessedTurn: 0,
      playerA: {
        arguments: [],
      },
      playerB: {
        arguments: [],
      },
    },
  },
  lastProcessedMessageId: {
    type: DataTypes.INTEGER,
    allowNull: true,
  },
  status: {
    type: DataTypes.STRING,
    allowNull: false,
    defaultValue: "idle",
  },
});

function linkDebateAnalysisModels({ Case }) {
  DebateAnalysis.belongsTo(Case, {foreignKey: "caseId", as: "case"});
}

module.exports = { DebateAnalysis, linkDebateAnalysisModels }; 

here's my debate_analysis model. So essentially what I am doing is, that previous analysis is stored in the DB. each time the debator submits an argument, the monitoring AI retrieves this previous analysis from the DB, inspects the most recent argument, and creates a similar analysis for the latest argument. we then append the most recent analysis to the DB along with the previous analysis. 

based on these fields, construct a prompt for the monitoring LLM

